41	Status FabricMemEngine::CheckInitialized() const {
42	  HIXL_CHK_BOOL_RET_STATUS(is_initialized_.load(std::memory_order_relaxed), FAILED,
43	                           "[FabricMemEngine] Engine is not initialized.");
