47	Status FabricMemEngine::ApplyVirtualMemoryConfig() const {
48	  if (fabric_mem_config_.has_capacity_tb) {
49	    HIXL_CHK_STATUS_RET(VirtualMemoryManager::GetInstance().SetVirtualMemoryCapacity(fabric_mem_config_.capacity_tb),
50	                        "[FabricMemEngine] Failed to set fabric memory capacity.");
51	  }
52	  if (fabric_mem_config_.has_start_address_tb) {
53	    HIXL_CHK_STATUS_RET(VirtualMemoryManager::GetInstance().SetGlobalStartAddress(fabric_mem_config_.start_address_tb),
54	                        "[FabricMemEngine] Failed to set fabric memory start address.");
55	  }
56	  return SUCCESS;
57	}
