59	Status FabricMemEngine::StartControlServer() {
60	  fabric_mem_control_server_ = MakeUnique<FabricMemControlServer>();
61	  FabricMemLocalMemory *local_memory = &local_memory_;
62	  auto provider = [local_memory](std::vector<ShareHandleInfo> &share_handles) -> Status {
63	    share_handles = local_memory->GetShareHandles();
64	    return SUCCESS;
65	  };
66	  HIXL_CHK_STATUS_RET(fabric_mem_control_server_->Start(local_engine_, provider),
67	                      "[FabricMemEngine] Failed to start fabric mem control server.");
68	  return SUCCESS;
69	}
