71	Status FabricMemEngine::InitTransferService() {
72	  FabricMemTransferServiceInitParam param;
73	  param.device_id = device_id_;
74	  param.max_stream_num = fabric_mem_config_.max_stream_num;
75	  param.task_stream_num = fabric_mem_config_.task_stream_num;
76	  param.local_engine = local_engine_;
77	  param.auto_connect = auto_connect_;
78	  param.statistic = &fabric_mem_statistic_;
79	  param.local_memory = &local_memory_;
80	  param.control_server = fabric_mem_control_server_.get();
81	  param.aclrt_context = aclrt_context_;
82	  param.enable_aicpu_unfold = fabric_mem_config_.enable_aicpu_unfold;
83	  if (fabric_mem_config_.enable_aicpu_unfold) {
84	    fabric_mem_transfer_service_ = std::make_shared<FabricMemAicpuTransferService>();
85	  } else {
86	    fabric_mem_transfer_service_ = std::make_shared<FabricMemHostTransferService>();
87	  }
88	  HIXL_CHK_STATUS_RET(fabric_mem_transfer_service_->Initialize(param),
89	                      "[FabricMemEngine] Failed to initialize fabric mem transfer service.");
90	  return SUCCESS;
91	}
