93	Status FabricMemEngine::InitFabricMem() {
94	  HIXL_DISMISSABLE_GUARD(fail_guard, ([this]() { CleanupFabricMemLocked(); }));
95	  HIXL_CHK_STATUS_RET(ApplyVirtualMemoryConfig(), "[FabricMemEngine] Failed to apply virtual memory config.");
96	  HIXL_CHK_STATUS_RET(VirtualMemoryManager::GetInstance().Initialize(),
97	                      "[FabricMemEngine] Failed to initialize fabric virtual memory manager.");
98	  HIXL_CHK_STATUS_RET(fabric_mem_statistic_.StartPeriodicDump(),
99	                      "[FabricMemEngine] Failed to start fabric mem statistic dump.");
100	  HIXL_CHK_STATUS_RET(StartControlServer(), "[FabricMemEngine] Failed to start control server.");
101	  HIXL_CHK_STATUS_RET(InitTransferService(), "[FabricMemEngine] Failed to initialize transfer service.");
102	  HIXL_DISMISS_GUARD(fail_guard);
103	  return SUCCESS;
104	}
