106	Status FabricMemEngine::InitializeLocked(const HixlOptions &options, bool &start_keepalive_monitor) {
107	  for (const auto &key : options.RawOptions()) {
108	    if (kSupportedOptions.find(key.first.GetString()) == kSupportedOptions.end()) {
109	      HIXL_LOGW("[FabricMemEngine] Unsupported option '%s' will be ignored", key.first.GetString());
110	    }
111	  }
112	  HIXL_CHK_BOOL_RET_STATUS(options.EnableFabricMem().value_or(false), PARAM_INVALID,
113	                           "[FabricMemEngine] EnableUseFabricMem must be 1.");
114	  HIXL_CHK_ACL_RET(aclrtGetDevice(&device_id_), "[FabricMemEngine] Failed to get device id.");
115	  TemporaryRtContext with_context(nullptr);
116	  HIXL_CHK_ACL_RET(aclrtCreateContext(&aclrt_context_, device_id_),
117	                   "[FabricMemEngine] Failed to create aclrt context.");
118	  aclrt_context_holder_ = std::shared_ptr<void>(aclrt_context_, [](void *ctx) {
119	    if (ctx != nullptr) {
120	      (void)aclrtDestroyContext(static_cast<aclrtContext>(ctx));
121	    }
122	  });
123	  HIXL_EVENT("[FabricMemEngine] Created aclrt ctx:%p, device:%d.", aclrt_context_, device_id_);
124	  HIXL_DISMISSABLE_GUARD(fail_guard, ([this]() {
125	                           if (aclrt_context_ != nullptr) {
126	                             aclrt_context_holder_.reset();
127	                             aclrt_context_ = nullptr;
128	                           }
129	                         }));
130	  TemporaryRtContext engine_context(aclrt_context_);
131	
132	  HIXL_CHK_STATUS_RET(ApplyFabricMemoryOptions(options), "[FabricMemEngine] Failed to apply fabric memory options.");
133	  auto_connect_ = options.AutoConnect().value_or(false);
134	
135	  HIXL_CHK_STATUS_RET(InitFabricMem(), "[FabricMemEngine] Failed to initialize.");
136	  is_initialized_ = true;
137	  int32_t listen_port = 0;
138	  std::string listen_ip;
139	  (void)ParseListenInfo(local_engine_, listen_ip, listen_port);
140	  start_keepalive_monitor = auto_connect_ || listen_port > 0;
141	  HIXL_DISMISS_GUARD(fail_guard);
142	  return SUCCESS;
143	}
