145	Status FabricMemEngine::ApplyFabricMemoryOptions(const HixlOptions &options) {
146	  fabric_mem_config_.enabled = true;
147	  fabric_mem_config_.enable_aicpu_unfold = true;
148	  fabric_mem_config_.task_stream_num = 1U;
149	  auto grc = options.GlobalResourceCfg();
150	  if (!grc.has_value()) {
151	    return SUCCESS;
152	  }
153	  if (grc->fabric_memory.max_capacity.has_value()) {
154	    fabric_mem_config_.capacity_tb = *grc->fabric_memory.max_capacity;
155	    fabric_mem_config_.has_capacity_tb = true;
156	  }
157	  if (grc->fabric_memory.start_address.has_value()) {
158	    fabric_mem_config_.start_address_tb = *grc->fabric_memory.start_address;
159	    fabric_mem_config_.has_start_address_tb = true;
160	  }
161	  fabric_mem_config_.enable_aicpu_unfold = grc->fabric_memory.enable_aicpu_unfold.value_or(true);
162	  if (fabric_mem_config_.enable_aicpu_unfold) {
163	    // AICPU unfold only supports task_stream_num=1.
164	    if (grc->fabric_memory.task_stream_num.has_value()) {
165	      HIXL_CHK_BOOL_RET_STATUS(*grc->fabric_memory.task_stream_num == 1U, PARAM_INVALID,
166	                               "[FabricMemEngine] enable_aicpu_unfold requires fabric_memory.task_stream_num=1, got "
167	                               "%zu.",
168	                               *grc->fabric_memory.task_stream_num);
169	    }
170	    fabric_mem_config_.task_stream_num = 1U;
171	  } else {
172	    fabric_mem_config_.task_stream_num = grc->fabric_memory.task_stream_num.value_or(1U);
173	  }
174	  return SUCCESS;
175	}
