177	Status FabricMemEngine::Initialize(const HixlOptions &options) {
178	  // Lock: mutex_.
179	  HIXL_LOGI("[FabricMemEngine] Initialization started, local_engine:%s", local_engine_.c_str());
180	  bool start_keepalive_monitor = false;
181	  {
182	    std::lock_guard<std::mutex> lock(mutex_);
183	    HIXL_CHK_STATUS_RET(InitializeLocked(options, start_keepalive_monitor), "[FabricMemEngine] Failed to initialize.");
184	    HIXL_LOGI("[FabricMemEngine] Initialization succeeded, local_engine:%s", local_engine_.c_str());
185	  }
186	  if (start_keepalive_monitor) {
187	    HIXL_CHK_STATUS_RET(fabric_mem_transfer_service_->StartKeepaliveMonitor(),
188	                        "[FabricMemEngine] Failed to start keepalive monitor, local_engine:%s", local_engine_.c_str());
189	  }
190	  return SUCCESS;
191	}
