193	Status FabricMemEngine::RegisterMem(const MemDesc &mem, MemType type, MemHandle &mem_handle) {
194	  // Lock: local memory share handle lock.
195	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[FabricMemEngine] Engine is not initialized.");
196	  TemporaryRtContext with_context(aclrt_context_);
197	  HIXL_LOGI("[FabricMemEngine] Registration started, type:%s, addr:%p, size:%lu", MemTypeToString(type).c_str(),
198	            reinterpret_cast<void *>(mem.addr), mem.len);
199	  HIXL_CHK_STATUS_RET(local_memory_.RegisterMem(mem, type, mem_handle), "[FabricMemEngine] Failed to register memory.");
200	  HIXL_LOGI("[FabricMemEngine] Registration succeeded, handle:%p.", mem_handle);
201	  return SUCCESS;
202	}
