204	Status FabricMemEngine::DeregisterMem(MemHandle mem_handle) {
205	  // Lock: local memory share handle lock.
206	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[FabricMemEngine] Engine is not initialized.");
207	  TemporaryRtContext with_context(aclrt_context_);
208	  HIXL_LOGI("[FabricMemEngine] Deregistration started, handle:%p.", mem_handle);
209	  HIXL_CHK_BOOL_RET_STATUS(!fabric_mem_transfer_service_->HasChannels(), FAILED,
210	                           "[FabricMemEngine] Disconnect peers before deregistering memory.");
211	  HIXL_CHK_STATUS_RET(local_memory_.DeregisterMem(mem_handle), "[FabricMemEngine] Failed to deregister memory.");
212	  return SUCCESS;
213	}
