229	void FabricMemEngine::Disconnect() {
230	  // Lock: none (delegates to transfer service facade).
231	  if (!is_initialized_.load(std::memory_order_relaxed) || fabric_mem_transfer_service_ == nullptr) {
232	    return;
233	  }
234	  TemporaryRtContext with_context(aclrt_context_);
235	  fabric_mem_transfer_service_->DisconnectAll();
236	}
