238	Status FabricMemEngine::EnsureAutoConnected(const AscendString &remote_engine) {
239	  if (!auto_connect_) {
240	    return SUCCESS;
241	  }
242	  constexpr int32_t kAutoConnectTimeoutMs = 3000;
243	  HIXL_CHK_STATUS_RET(fabric_mem_transfer_service_->EnsureConnected(remote_engine, kAutoConnectTimeoutMs),
244	                      "[FabricMemEngine] Auto-connect failed, remote:%s.", remote_engine.GetString());
245	  return SUCCESS;
246	}
247	
248	void FabricMemEngine::DisconnectOnTransferError(const AscendString &remote_engine) {
249	  if (!auto_connect_) {
250	    return;
251	  }
252	  const Status ret = fabric_mem_transfer_service_->Disconnect(remote_engine, 0);
253	  if (ret != SUCCESS && ret != NOT_CONNECTED) {
254	    HIXL_LOGW("[FabricMemEngine] Failed to disconnect on transfer error, remote:%s, ret:%u.", remote_engine.GetString(),
255	              static_cast<uint32_t>(ret));
256	  }
257	}
