259	Status FabricMemEngine::TransferSync(const AscendString &remote_engine, TransferOp operation,
260	                                     const std::vector<TransferOpDesc> &op_descs, int32_t timeout_in_millis) {
261	  // Lock: none (transfer service routes via channel manager + slot pool).
262	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[FabricMemEngine] Engine is not initialized.");
263	  TemporaryRtContext with_context(aclrt_context_);
264	  HIXL_CHK_BOOL_RET_STATUS(!op_descs.empty(), PARAM_INVALID,
265	                           "[FabricMemEngine] TransferSync failed, op_descs is empty.");
266	  HIXL_CHK_STATUS_RET(EnsureAutoConnected(remote_engine), "[FabricMemEngine] Failed to prepare transfer.");
267	  const Status ret =
268	      fabric_mem_transfer_service_->TransferSync(remote_engine.GetString(), operation, op_descs, timeout_in_millis);
269	  if (ret != SUCCESS) {
270	    DisconnectOnTransferError(remote_engine);
271	    return ret;
272	  }
273	  return SUCCESS;
274	}
