276	Status FabricMemEngine::TransferAsync(const AscendString &remote_engine, TransferOp operation,
277	                                      const std::vector<TransferOpDesc> &op_descs, const TransferArgs &optional_args,
278	                                      TransferReq &req) {
279	  // Lock: none (transfer service owns async record on success).
280	  (void)optional_args;
281	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[FabricMemEngine] Engine is not initialized.");
282	  TemporaryRtContext with_context(aclrt_context_);
283	  req = nullptr;
284	  HIXL_CHK_BOOL_RET_STATUS(!op_descs.empty(), PARAM_INVALID,
285	                           "[FabricMemEngine] TransferAsync failed, op_descs is empty.");
286	  HIXL_CHK_STATUS_RET(EnsureAutoConnected(remote_engine), "[FabricMemEngine] Failed to prepare transfer.");
287	  TransferReq new_req = nullptr;
288	  const Status ret =
289	      fabric_mem_transfer_service_->TransferAsync(remote_engine.GetString(), operation, op_descs, new_req);
290	  if (ret != SUCCESS) {
291	    DisconnectOnTransferError(remote_engine);
292	    return ret;
293	  }
294	  req = new_req;
295	  return SUCCESS;
296	}
