298	Status FabricMemEngine::GetTransferStatus(const TransferReq &req, TransferStatus &status) {
299	  // Lock: transfer service per-channel submit gate and records lock (poll).
300	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[FabricMemEngine] Engine is not initialized.");
301	  AsyncTransferPollInfo poll_info;
302	  Status ret = fabric_mem_transfer_service_->GetTransferStatus(req, status, &poll_info);
303	  if (ret != SUCCESS) {
304	    HIXL_LOGE(ret, "[FabricMemEngine] GetTransferStatus failed, req:%p, ret:%u.", req, static_cast<uint32_t>(ret));
305	    if (ret != NOT_CONNECTED) {
306	      fabric_mem_transfer_service_->CleanupAsyncTransfer(req);
307	    }
308	    return ret;
309	  }
310	  if (status != TransferStatus::WAITING) {
311	    if (status == TransferStatus::COMPLETED) {
312	      const auto prof_type =
313	          (poll_info.op_type == READ ? HixlProfType::HixlOpBatchRead : HixlProfType::HixlOpBatchWrite);
314	      HIXL_API_PROFILING_WITH_TIME(prof_type, poll_info.prof_start_time);
315	    }
316	    if (status == TransferStatus::FAILED) {
317	      DisconnectOnTransferError(AscendString(poll_info.channel_id.c_str()));
318	    }
319	  }
320	  return SUCCESS;
321	}
