329	void FabricMemEngine::CleanupFabricMemLocked() {
330	  is_initialized_ = false;
331	  {
332	    TemporaryRtContext with_context(aclrt_context_);
333	    // Finalize the transfer service first: it stops the keepalive monitor and disconnects every
334	    // remote (aborting in-flight transfers, unmapping remote memory, releasing slots).
335	    if (fabric_mem_transfer_service_ != nullptr) {
336	      fabric_mem_transfer_service_->Finalize();
337	      fabric_mem_transfer_service_.reset();
338	    }
339	    if (fabric_mem_control_server_ != nullptr) {
340	      fabric_mem_control_server_->Stop();
341	      fabric_mem_control_server_.reset();
342	    }
343	    local_memory_.Finalize();
344	    fabric_mem_statistic_.StopPeriodicDump();
345	  }
346	  if (aclrt_context_ != nullptr) {
347	    aclrt_context_holder_.reset();
348	    aclrt_context_ = nullptr;
349	  }
350	}
351	
352	void FabricMemEngine::Finalize() {
353	  // Lock: mutex_.
354	  HIXL_LOGI("[FabricMemEngine] Finalization started");
355	  {
356	    std::lock_guard<std::mutex> lock(mutex_);
357	    CleanupFabricMemLocked();
358	  }
359	  HIXL_LOGI("[FabricMemEngine] Finalization succeeded");
360	}
