362	Status FabricMemEngine::SendNotify(const AscendString &remote_engine, const NotifyDesc &notify,
363	                                   int32_t timeout_in_millis) {
364	  // Lock: none.
365	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[FabricMemEngine] Engine is not initialized.");
366	  TemporaryRtContext with_context(aclrt_context_);
367	  HIXL_CHK_BOOL_RET_STATUS(notify.name.GetLength() <= kMaxNotifyNameLen, PARAM_INVALID,
368	                           "[FabricMemEngine] notify.name length exceed max limit:%zu, current:%zu.", kMaxNotifyNameLen,
369	                           notify.name.GetLength());
370	  HIXL_CHK_BOOL_RET_STATUS(notify.notify_msg.GetLength() <= kMaxNotifyMsgLen, PARAM_INVALID,
371	                           "[FabricMemEngine] notify.notify_msg length exceed max limit:%zu, current:%zu.",
372	                           kMaxNotifyMsgLen, notify.notify_msg.GetLength());
373	  HIXL_LOGI("[FabricMemEngine] Sending notify to remote:%s, name:%s", remote_engine.GetString(),
374	            notify.name.GetString());
375	  HIXL_CHK_STATUS_RET(FabricMemControlClient::SendNotify(remote_engine.GetString(), notify, timeout_in_millis),
376	                      "[FabricMemEngine] Failed to send notify to remote:%s.", remote_engine.GetString());
377	  HIXL_EVENT("[FabricMemEngine] Notify sent, remote:%s, name:%s", remote_engine.GetString(), notify.name.GetString());
378	  return SUCCESS;
379	}
