381	Status FabricMemEngine::GetNotifies(std::vector<NotifyDesc> &notifies) {
382	  // Lock: none (control server internal lock).
383	  HIXL_CHK_STATUS_RET(CheckInitialized(), "[FabricMemEngine] Engine is not initialized.");
384	  TemporaryRtContext with_context(aclrt_context_);
385	  HIXL_CHK_STATUS_RET(fabric_mem_control_server_->DequeueNotifies(notifies),
386	                      "[FabricMemEngine] Failed to dequeue notifies.");
387	  return SUCCESS;
388	}
